149	static void health_session_start(void)
150	{
151	    int hot = (g_weather.cur_temp >= CFG_I("water_hot_temp_c", WATER_HOT_TEMP_C)) ? 1 : 0;
152	
153	    g_seated = true;
154	    g_water_level = 0;
155	    g_water_total_s = hot ? CFG_I("water_hot_l1_s", WATER_HOT_L1_S)
156	                          : CFG_I("water_l1_s", WATER_L1_S);
157	    g_water_remain_s = g_water_total_s;
158	    g_sit_level = 0;
159	    g_sit_total_s = CFG_I("sit_l1_s", SIT_L1_S);
160	    g_sit_remain_s = CFG_I("sit_l1_s", SIT_L1_S);
161	
162	    LV_LOG_USER("[health] seated, water=%ds(%s), sit=%ds",
163	                g_water_total_s, hot ? "hot" : "normal", g_sit_total_s);
164	    health_evt(DM_HEALTH_EVT_PRESENCE, 1);
165	    health_evt(DM_HEALTH_EVT_RING, 0);
166	}
