static void health_popup_left_cb(lv_event_t *e)
{
    (void)e;
    reset_idle_timer();
    if (health_popup_kind == 0)
        dm_health_water_drank();
    else
        dm_health_sit_stood();
    health_popup_hide();
}

static void health_popup_right_cb(lv_event_t *e)
{
    (void)e;
    reset_idle_timer();
    if (health_popup_kind == 0)
        dm_health_water_snooze();
    else
        dm_health_sit_snooze();
    health_popup_hide();
}

