309	static int shtc3_send_cmd(FAR struct shtc3_dev_s *priv, uint16_t cmd) {
310	
311	  struct i2c_msg_s msg;
312	  uint8_t txbuffer[2];
313	  int ret;
314	  int retries = 3;
315	
316	  up_mdelay(20);                       /* 增加到20ms */
317	  txbuffer[0] = (uint8_t)(cmd >> 8);   /* 高字节先发 */
318	  txbuffer[1] = (uint8_t)(cmd & 0xFF); /* 低字节后发 */
319	
320	  msg.frequency = priv->freq;
321	  msg.addr = priv->addr;
322	  msg.flags = 0;
323	  msg.buffer = txbuffer;
324	  msg.length = 2;
325	
326	  /* 添加重试机制 */
327	  while (retries--) {
328	    ret = I2C_TRANSFER(priv->i2c, &msg, 1);
329	    if (ret >= 0) {
330	
331	      return OK;
332	    }
333	    syslog(LOG_ERR,
334	           "Failed to send command 0x%04X, retrying (%d attempts left)\n", cmd,
335	           retries);
336	    /* 失败后短暂延时再重试 */
337	    //
338	    if (retries > 0) {
339	      /* 短暂延时后重试 */
340	      up_mdelay(10);
341	    }
342	  }
343	
344	  syslog(LOG_ERR, "Failed to send command 0x%04X: %d\n", cmd, ret);
345	  return -EIO;
346	}
